class Solution { fun waysToReachTarget(target:Int,types:Array<IntArray>):Int{val mod=1_000_000_007;var dp=IntArray(target+1);dp[0]=1;for(type in types){val next=IntArray(target+1);for(score in 0..target)if(dp[score]!=0){var take=0;while(take<=type[0]&&score+take*type[1]<=target){val newScore=score+take*type[1];next[newScore]+=dp[score];if(next[newScore]>=mod)next[newScore]-=mod;take++}};dp=next};return dp[target]} }
